//! Aviate's geomagnetic reference, from the wire to the typed variation.

#![allow(clippy::expect_used, clippy::panic)]

use std::sync::{Arc, Mutex};
use std::time::Instant;

use pilotage_adapter_api::{MagneticVariationSource, MeasurementClock, SourceRole};

use super::fc_magnetic_variation;
use crate::link::LinkState;

// AVIATE_GEOMAGNETIC_REFERENCE frames as Aviate sends them (its golden
// frames, generated by pymavlink 2.4.41 from aviate.xml), sysid 1 compid 1.
// Model source, declination -0.2113 rad.
const MODEL_FRAME: &[u8] = &[
    0xFD, 0x0D, 0x00, 0x00, 0x03, 0x01, 0x01, 0x21, 0x4E, 0x00, 0x00, 0x09, 0x3D, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x07, 0x5F, 0x58, 0xBE, 0x01, 0x02, 0x36,
];
// No variation applied: NaN declination, source 0 trimmed by MAVLink 2
// trailing-zero truncation to a 12-byte payload.
const NONE_FRAME: &[u8] = &[
    0xFD, 0x0C, 0x00, 0x00, 0x04, 0x01, 0x01, 0x21, 0x4E, 0x00, 0x00, 0x09, 0x3D, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0xC0, 0x7F, 0x93, 0x73,
];

fn received(frame: &[u8]) -> Arc<Mutex<LinkState>> {
    let mut messages = Vec::new();
    let stats = crate::codec::parse_datagram(frame, &mut messages);
    assert_eq!(stats.crc_failures, 0, "the frame verifies");
    assert_eq!(messages.len(), 1, "the frame decodes: {messages:?}");
    let state = Arc::new(Mutex::new(LinkState::default()));
    crate::link::apply_messages_at(&state, &messages, 0, 0, Instant::now());
    state
}

#[test]
fn a_model_reference_becomes_an_fc_model_variation() {
    let state = received(MODEL_FRAME);
    let latest = state.lock().expect("link state");
    let update = latest.geomagnetic_reference.expect("the report is cached");
    let variation = fc_magnetic_variation(&update, &latest).expect("a known source");
    assert_eq!(variation.source, MagneticVariationSource::FcModel);
    assert_eq!(variation.declination_rad, -0.2113);
    assert_eq!((variation.model_id, variation.model_epoch), (None, None));
    assert_eq!(variation.stamp.role, SourceRole::OperationalEstimate);
    assert_eq!(variation.stamp.clock, MeasurementClock::HostMonotonic);
}

#[test]
fn a_truncated_none_reference_becomes_a_magnetic_statement() {
    let state = received(NONE_FRAME);
    let latest = state.lock().expect("link state");
    let update = latest.geomagnetic_reference.expect("the report is cached");
    let variation = fc_magnetic_variation(&update, &latest).expect("NONE is a source");
    assert_eq!(variation.source, MagneticVariationSource::None);
}

#[test]
fn an_unknown_source_code_states_no_variation() {
    let frame_state = LinkState {
        geomagnetic_reference: Some(crate::link::GeomagneticReferenceUpdate {
            declination_rad: 0.1,
            source: 9,
            sequence: 0,
            received_since_start_ns: 0,
            received_at: Instant::now(),
        }),
        ..LinkState::default()
    };
    let update = frame_state.geomagnetic_reference.expect("set above");
    assert!(fc_magnetic_variation(&update, &frame_state).is_none());
}

#[test]
fn each_report_advances_the_lane_sequence() {
    let mut messages = Vec::new();
    crate::codec::parse_datagram(MODEL_FRAME, &mut messages);
    crate::codec::parse_datagram(MODEL_FRAME, &mut messages);
    let state = Arc::new(Mutex::new(LinkState::default()));
    crate::link::apply_messages_at(&state, &messages, 0, 0, Instant::now());
    let latest = state.lock().expect("link state");
    assert_eq!(latest.geomagnetic_reference.map(|u| u.sequence), Some(1));
}
